        public bool CheckPaidAllOrderItemInVisitOrder(int visitOrderID)
        {
            DataSet ds = dal.GetDataSet("MEVisitOrderItems_GetVisitOrderItemListByVisitOrderIDAndNotDetailOfPackageItem", visitOrderID);
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    MEVisitOrderItemsInfo objVisitOrderItemsInfo = (MEVisitOrderItemsInfo)GetObjectFromDataRow(row);
                    if (objVisitOrderItemsInfo.MEVisitOrderItemStatus != BOSCommon.VisitOrderStatus.Paid.ToString())
                        return false;
                }
                return true;
            }
            return true;
        }

        /// <summary>
        /// Get salary commission by employee and date
        /// </summary>
        /// <param name="employeeID"></param>
        /// <param name="salaryDate"></param>
        /// <returns></returns>
        public double GetSalaryCommissionByEmployeeAndDate(int employeeID, DateTime salaryDate)
        {
            double salaryCommission = 0;
            DataSet ds = dal.GetDataSet("MEVisitOrderItems_GetSalaryCommissionByEmployeeAndDate", employeeID, salaryDate);
            if (ds.Tables[0].Rows.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    double commision = (Convert.ToDouble(row[0]) * Convert.ToDouble(row[1])) / 100;
                    salaryCommission += commision;
                }
            }
            return salaryCommission;
        }

